ins_points as (
  insert into sermon_points (sermon_id, position, heading, detail, scriptures)
  values
    ((select id from s), 1, 'Why the church needs the Creed', 'The Creed is a summary of what we believe - a discipleship anchor so believers can stand their ground and answer the hard questions raised in evangelism (who is Jesus, what is the Trinity). Two aims: stand firm yourself, and help the questioner come to Christ.', '{}'::text[]),
    ((select id from s), 2, 'One God', 'The Creed opens ''I believe in one God, the Father Almighty.'' Our God is one, not three - the foundation everything else is built on.', '{}'::text[]),
    ((select id from s), 3, 'Jesus is true God from true God', 'Born in a moment of confusion (c.325 AD): the presbyter Arius said Jesus was exalted above creation but not truly God. Emperor Constantine summoned the Council of Nicaea, and the church answered from Scripture - Jesus is God from God, Light from light, true God from true God, begotten not made, of one substance with the Father.', '{"John 1:1-14","Colossians 1:15"}'::text[]),
    ((select id from s), 4, 'For us and for our salvation He came down', 'The incarnation: ''for us and for our salvation He came down from heaven'' and was made flesh (the Word became flesh). God stepped down for us - crucified under Pontius Pilate, suffered, buried, and rose the third day.', '{"John 1:14"}'::text[]),
    ((select id from s), 5, 'One God in three persons', 'The Father is God, the Son is God, the Holy Spirit is God - not three gods but one God in three persons. The Creed helps the church say with clarity what Scripture reveals with authority.', '{}'::text[]),
    ((select id from s), 6, 'Respond to this God', 'The cross and resurrection are true. This is the God you must respond to - not merely to admire Jesus but to trust and surrender to Him. Altar call to give or recommit your life to Christ.', '{}'::text[])
  returning 1
)
,
ins_scr as (
  insert into sermon_scriptures (sermon_id, reference, book, chapter, verse_start, verse_end, role)
  values
    ((select id from s), 'John 1:1-14', 'John', 1, 1, 14, 'anchor'),
    ((select id from s), 'Colossians 1:15', 'Colossians', 1, 15, 15, 'supporting'),
    ((select id from s), '1 Timothy 3:16', '1 Timothy', 3, 16, 16, 'supporting')
  returning 1
)
,
ins_clips as (
  insert into sermon_clips (sermon_id, rank, hook, theme, timestamp_hint, platforms, status, care_flag, care_note)
  values
    ((select id from s), 1, 'True God from true God, begotten not made', 'who Jesus is', '~12:04', '{reel,short}'::text[], 'to_caption', false, null),
    ((select id from s), 2, 'For us and for our salvation, He came down from heaven - the Word was made flesh', 'incarnation', '~12:07', '{reel}'::text[], 'to_caption', false, null),
    ((select id from s), 3, 'Not three gods, but one God in three persons', 'the Trinity', '~12:39', '{reel,short}'::text[], 'to_caption', false, null),
    ((select id from s), 4, 'The Nicene Creed was born in a moment of confusion', 'church history / Nicaea', '~12:03', '{reel,carousel}'::text[], 'to_caption', false, null),
    ((select id from s), 5, 'Is this the God you believe in? You must respond', 'the response', '~12:41', '{reel,short}'::text[], 'to_caption', false, null)
  returning 1
)
,
ins_tags as (
  insert into sermon_tags (name) values ('doctrine'),('nicene creed'),('christology'),('trinity'),('salvation'),('apologetics')
  on conflict (name) do nothing
  returning 1
)
insert into sermon_tag_map (sermon_id, tag_id)
select (select id from s), t.id from sermon_tags t
where t.name in ('doctrine','nicene creed','christology','trinity','salvation','apologetics')
on conflict do nothing;

-- VERIFY
select service_date, title, preacher, is_guest, series, anchor_scripture,
  (select count(*) from sermon_points p     where p.sermon_id = s.id) as points,
  (select count(*) from sermon_scriptures x where x.sermon_id = s.id) as scriptures,
  (select count(*) from sermon_clips c      where c.sermon_id = s.id) as clips
from sermons s where service_date = '2026-07-19';
